"""Retry with exponential backoff for rate-limited external calls."""

from __future__ import annotations

import time
from collections.abc import Callable


class RateLimited(Exception):
    """An external service answered HTTP 429."""

    reason_code = "RATE_LIMITED"


def retry_with_backoff[T](
    fn: Callable[[], T], attempts: int = 5, base_delay: float = 0.02, max_delay: float = 0.5
) -> T:
    """Call ``fn`` until it returns, re-running it whole after each ``RateLimited``."""
    for attempt in range(attempts):
        try:
            return fn()
        except RateLimited:
            if attempt == attempts - 1:
                raise
            time.sleep(min(max_delay, base_delay * 2**attempt))
    raise AssertionError("unreachable")

"""The practice ledger's tools: an FX rate lookup and the books API (``post_line`` books)."""

from __future__ import annotations

from decimal import Decimal
from typing import Any

from neatlogs import span

from hostkit import external
from practice_ledger.retry import RateLimited


class FxUnavailable(RuntimeError):
    reason_code = "FX_UNAVAILABLE"


class BooksError(RuntimeError):
    reason_code = "BOOKS_ERROR"


@span(kind="TOOL", name="fx_rate")
def fx_rate(currency: str, date: str) -> Decimal:
    """USD per unit of ``currency`` on ``date``."""
    response = external.call("fx", "GET", "/rate", params={"currency": currency, "date": date})
    if response.status_code == 429:
        raise RateLimited(f"fx_rate {currency}: HTTP 429")
    if response.status_code >= 400:
        raise FxUnavailable(f"fx_rate {currency}: HTTP {response.status_code}")
    return Decimal(str(response.json()["rate"]))


@span(kind="TOOL", name="post_line")
def post_line(line: dict[str, Any]) -> None:
    """Book one journal line. The books API has no idempotency: posting twice books twice."""
    response = external.call("books", "POST", "/lines", json=line)
    if response.status_code >= 400:
        raise BooksError(f"post_line {line.get('key')}: HTTP {response.status_code}")


@span(kind="TOOL", name="list_lines")
def list_lines(ref: str) -> list[dict[str, Any]]:
    response = external.call("books", "GET", "/lines", params={"ref": ref})
    if response.status_code >= 400:
        raise BooksError(f"list_lines {ref}: HTTP {response.status_code}")
    return list(response.json()["lines"])

"""Booking a document's lines in USD, exactly once each.

A document becomes a ``Batch`` of lines in its own currency. ``reconcile`` converts each line
through ``fx_rate`` (an external API that may rate-limit) and books it through ``post_line``. A
429 re-runs the whole attempt, so the ``PostingSession`` remembers which lines are already
booked and where to resume: a retry never books a line twice.
"""

from __future__ import annotations

from collections.abc import Iterable
from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal
from typing import Any

from practice_ledger.retry import RateLimited, retry_with_backoff
from practice_ledger.tools import fx_rate, post_line

CENT = Decimal("0.01")


@dataclass(frozen=True)
class Line:
    key: str
    account: str
    amount: Decimal  # document currency
    currency: str
    date: str


@dataclass(frozen=True)
class Batch:
    ref: str
    lines: tuple[Line, ...]


def build_batch(document: dict[str, Any]) -> Batch:
    ref, currency, date = document["ref"], document["currency"], document["date"]
    lines = tuple(
        Line(f"{ref}#{n}", item["account"], Decimal(item["amount"]), currency, date)
        for n, item in enumerate(document["items"], 1)
    )
    return Batch(ref, lines)


class PostingSession:
    """Which lines of one batch are booked, and where to resume."""

    def __init__(self, batch: Batch) -> None:
        self.batch = batch
        self.booked: set[str] = set()
        self.cursor = 0

    @property
    def done(self) -> bool:
        return self.cursor >= len(self.batch.lines)

    def pending(self) -> tuple[Line, ...]:
        return self.batch.lines[self.cursor :]

    def book(self, line: Line, rate: Decimal) -> None:
        if line.key not in self.booked:
            usd = (line.amount * rate).quantize(CENT, rounding=ROUND_HALF_UP)
            post_line({"key": line.key, "ref": self.batch.ref, "account": line.account,
                       "amount_cents": int(usd * 100), "date": line.date})  # fmt: skip
            self.booked.add(line.key)
        self.cursor += 1


def reconcile(batch: Batch, session: PostingSession | None = None) -> PostingSession:
    session = session or PostingSession(batch)  # outside the retried scope: survives retries

    def attempt() -> PostingSession:
        for line in session.pending():
            session.book(line, fx_rate(line.currency, line.date))
        return session

    return retry_with_backoff(attempt)


def batch_worker(
    batches: Iterable[Batch], sessions: dict[str, PostingSession] | None = None
) -> dict[str, PostingSession]:
    """Reconcile a queue of batches. A batch still rate-limited after its retries keeps its
    session, so the next pass resumes it where it stopped instead of starting over."""
    sessions = {} if sessions is None else sessions
    for batch in batches:
        session = sessions.setdefault(batch.ref, PostingSession(batch))
        if session.done:
            continue
        try:
            reconcile(batch, session)
        except RateLimited:
            continue  # resumed on the next pass
    return sessions

"""A deterministic FX API: ``GET /rate?currency=EUR&date=2026-09-14`` → ``{"rate": "1.0912"}``."""

from __future__ import annotations

import datetime as dt
import time
from collections.abc import Mapping
from decimal import Decimal
from typing import Any

USD_PER_UNIT = {
    "USD": Decimal("1"),
    "EUR": Decimal("1.0850"),
    "GBP": Decimal("1.2700"),
    "JPY": Decimal("0.006720"),
    "INR": Decimal("0.011950"),
    "CAD": Decimal("0.7350"),
}
SERVICE_TIME_S = 0.008  # a paid API is not free in latency either


def rate(currency: str, date: str) -> Decimal:
    if currency == "USD":
        return Decimal(1)
    day = dt.date.fromisoformat(date).toordinal()
    wobble = Decimal(1) + Decimal((day % 17) - 8) / Decimal(1000)
    return (USD_PER_UNIT[currency] * wobble).quantize(Decimal("0.000001"))


def handle(method: str, path: str, query: Mapping[str, str], body: bytes) -> tuple[int, Any]:
    time.sleep(SERVICE_TIME_S)
    if method != "GET" or path != "/rate":
        return 404, {"error": "not found"}
    currency, date = query.get("currency", ""), query.get("date", "")
    if currency not in USD_PER_UNIT:
        return 400, {"error": f"unsupported currency {currency!r}"}
    try:
        value = rate(currency, date)
    except ValueError:
        return 400, {"error": f"bad date {date!r}"}
    return 200, {"currency": currency, "date": date, "rate": str(value)}

"""A books API, one ledger per task: ``POST /lines`` books (no idempotency),
``GET /lines?ref=…`` lists a document's lines, ``GET /lines/<key>`` fetches one line."""

from __future__ import annotations

import json
import threading
import time
from collections.abc import Mapping
from typing import Any

SERVICE_TIME_S = 0.012
_books: dict[str, list[dict[str, Any]]] = {}
_lock = threading.Lock()


def reset() -> None:
    with _lock:
        _books.clear()


def handle(
    method: str, path: str, query: Mapping[str, str], body: bytes, namespace: str = ""
) -> tuple[int, Any]:
    time.sleep(SERVICE_TIME_S)
    with _lock:
        lines = _books.setdefault(namespace, [])
        if method == "POST" and path == "/lines":
            line = json.loads(body or b"{}")
            if not isinstance(line, dict) or "key" not in line:
                return 400, {"error": "a line needs a key"}
            lines.append(dict(line))
            return 201, {"booked": line["key"]}
        if method == "GET" and path == "/lines":
            ref = query.get("ref")
            return 200, {"lines": [dict(x) for x in lines if ref is None or x.get("ref") == ref]}
        if method == "GET" and path.startswith("/lines/"):
            key = path.removeprefix("/lines/")
            found = [dict(x) for x in lines if x.get("key") == key]
            return (200, {"line": found[0]}) if found else (404, {"error": "no such line"})
    return 404, {"error": "not found"}

